                return ADCS_E_RANGE;
            }
        }
    }

    // 4. Degenerate check: quaternion norm squared <= 1e-12
    double norm_sq = q_bi->w * q_bi->w + q_bi->x * q_bi->x + 
                     q_bi->y * q_bi->y + q_bi->z * q_bi->z;
    if (norm_sq <= 1.0e-12) {
        // Failure output zero
        for (i = 0; i < 3; i++) {
            for (j = 0; j < 3; j++) {
                covariance_b->m[i][j] = 0.0;
            }
        }
        return ADCS_E_DEGENERATE;
    }

    // 5. Normalize quaternion to get unit quaternion
    double n = sqrt(norm_sq);
    adcs_quat_t q_unit;
    q_unit.w = q_bi->w / n;
    q_unit.x = q_bi->x / n;
    q_unit.y = q_bi->y / n;
    q_unit.z = q_bi->z / n;

